private int idx = 0;
TreeNode build(int[] pre, int bound) {     // first call: bound = Integer.MAX_VALUE
    if (idx == pre.length || pre[idx] > bound) return null;
    TreeNode root = new TreeNode(pre[idx++]);
    root.left = build(pre, root.val);
    root.right = build(pre, bound);
    return root;
}

boolean valid(TreeNode n, long lo, long hi) {   // called with Long.MIN_VALUE, Long.MAX_VALUE
    if (n == null) return true;
    if (n.val <= lo || n.val >= hi) return false;
    return valid(n.left, lo, n.val) && valid(n.right, n.val, hi);
}
